frappe.query_reports["Withholding Tax Summary on Sales for Properties"] = {
    "filters": [
        {
            "fieldname": "from_date",
            "label": __("From Date"),
            "fieldtype": "Date",
            "default": frappe.datetime.add_months(frappe.datetime.get_today(), -1)
        },
        {
            "fieldname": "to_date",
            "label": __("To Date"),
            "fieldtype": "Date",
            "default": frappe.datetime.get_today()
        },
        {
            "fieldname": "property",
            "label": __("Property"),
            "fieldtype": "Link",
            "options": "Property"
        },
        {
            "fieldname": "unit",
            "label": __("Unit"),
            "fieldtype": "Link",
            "options": "Unit Master",
            "get_query": function() {
                const property = frappe.query_report.get_filter_value("property");
                return property ? { filters: { property: property } } : {};
            }
        },
        {
            "fieldname": "tenant",
            "label": __("Tenant"),
            "fieldtype": "Link",
            "options": "Customer"
        }
    ]
};
